// ─── File: IdempotentConsumerDemo.java ───
// Runnable demo: three idempotency techniques vs at-least-once duplicates.
package com.bank.idemconsumer;

import java.math.BigDecimal;
import java.util.logging.*;

public class IdempotentConsumerDemo {

    private static final Logger log = Logger.getLogger("IdemConsumer");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // 1) Inbox-guarded credit (general side effect)
        InboxStore inbox = new InboxStore();
        BalanceStore balances = new BalanceStore(inbox);
        balances.set("CUR3001", new BigDecimal("250000"));
        balances.creditIdempotent("EVT-1", "CUR3001", new BigDecimal("50000"));
        balances.creditIdempotent("EVT-1", "CUR3001", new BigDecimal("50000")); // dup
        log.info(() -> "CUR3001 after duplicate credit = Rs." + balances.get("CUR3001"));

        // 2) Unique constraint on natural key (inserts)
        SettlementStore settlements = new SettlementStore();
        log.info(() -> "Settle TRD-7: " + settlements.settle("TRD-7"));
        log.info(() -> "Settle TRD-7 again: " + settlements.settle("TRD-7")); // dup
        log.info(() -> "Settlement rows = " + settlements.rowCount());

        // 3) Idempotent state transition (state machine)
        OrderStore orders = new OrderStore();
        orders.place("ORD-9");
        log.info(() -> "Ship ORD-9: " + orders.ship("ORD-9"));
        log.info(() -> "Ship ORD-9 again: " + orders.ship("ORD-9")); // dup → no-op
        log.info(() -> "ORD-9 final status = " + orders.status("ORD-9"));
    }
}

// ─── inbox/InboxStore.java (processed_event_id table) ───
class InboxStore {
    private final java.util.concurrent.ConcurrentHashMap<String, Boolean> processed =
            new java.util.concurrent.ConcurrentHashMap<>();
    // Atomic claim in the SAME transaction as the business change (simulated).
    boolean claim(String eventId) {
        return processed.putIfAbsent(eventId, Boolean.TRUE) == null;
    }
}

// ─── balance/BalanceStore.java (inbox-guarded credit) ───
class BalanceStore {
    private static final Logger log = Logger.getLogger("IdemConsumer");
    private final java.util.concurrent.ConcurrentHashMap<String, BigDecimal> db =
            new java.util.concurrent.ConcurrentHashMap<>();
    private final InboxStore inbox;
    BalanceStore(InboxStore inbox) { this.inbox = inbox; }
    void set(String id, BigDecimal b) { db.put(id, b); }
    BigDecimal get(String id) { return db.get(id); }
    // One transaction: claim event id + credit. Duplicate → skip.
    void creditIdempotent(String eventId, String account, BigDecimal amount) {
        if (!inbox.claim(eventId)) {
            log.info(() -> "DUPLICATE " + eventId + " skipped (already in inbox)");
            return;
        }
        db.merge(account, amount, BigDecimal::add);
        log.info(() -> "Credited " + account + " Rs." + amount + " from " + eventId);
    }
}

// ─── settlement/SettlementStore.java (UNIQUE natural key) ───
class SettlementStore {
    private final java.util.Set<String> tradeIds =
            java.util.concurrent.ConcurrentHashMap.newKeySet();
    // Simulates INSERT with UNIQUE(trade_id): false on duplicate.
    String settle(String tradeId) {
        return tradeIds.add(tradeId) ? "SETTLED" : "DUPLICATE (unique trade_id) skipped";
    }
    int rowCount() { return tradeIds.size(); }
}

// ─── order/OrderStore.java (idempotent state transition) ───
class OrderStore {
    enum Status { PLACED, SHIPPED }
    private final java.util.concurrent.ConcurrentHashMap<String, Status> statuses =
            new java.util.concurrent.ConcurrentHashMap<>();
    void place(String id) { statuses.put(id, Status.PLACED); }
    // Conditional transition: only PLACED → SHIPPED; duplicate is a no-op.
    String ship(String id) {
        Status prev = statuses.computeIfPresent(id,
                (k, cur) -> cur == Status.PLACED ? Status.SHIPPED : cur);
        return prev == Status.SHIPPED ? "SHIPPED (applied or already)" : "unknown";
    }
    Status status(String id) { return statuses.get(id); }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
